   const patient=ownVisit(data.state,data.mine);
   if(!patient||data.mine!==credentials.token)throw Error('Visit not found');
   setState(data.state);stateRef.current=data.state;
   setRoom(credentials.room);roomRef.current=credentials.room;
   storageSet(localStorage,'careflow-room',credentials.room);
   const url=new URL(location.href);url.searchParams.set('room',credentials.room);history.replaceState(null,'',url);
   setMine(data.mine);setOwnedToken(data.mine);setClaim(credentials.access);
   setVisitCode('');
