 async function switchFamily(token:string){if(busyRef.current)return;busyRef.current=true;setBusy(true);try{const response=await fetch(`/api/rooms/${room}/family`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})});const data=await response.json();if(!response.ok)throw Error(data.error);acceptVisit(data)}catch(error){setToast(error instanceof Error?error.message:'Could not switch visit')}finally{busyRef.current=false;setBusy(false)}}
 async function forgetFamily(){if(!confirm('Forget all saved family visits on this device? Keep your private slip codes to log in again.'))return;setBusy(true);try{const response=await fetch(`/api/rooms/${room}/family`,{method:'DELETE'});if(!response.ok)throw Error();setFamily([]);setMine('');setOwnedToken('');setClaim('');setEntered(false);for(let i=sessionStorage.length-1;i>=0;i--){const key=sessionStorage.key(i);if(key?.startsWith('cf-private-code:'+room))sessionStorage.removeItem(key)}}catch{setToast('Could not forget saved visits. Please retry.')}finally{setBusy(false)}}
 function chooseLanguage(value:Language){
  const option=languages.find(([code])=>code===value);
  if(!option)return;
  setLang(value);storageSet(localStorage,'cf-language-selected',value);
  storageSet(localStorage,'cf-language',value);
  // This confirmation stays visible even if speech is unavailable or muted.
  setToast(`${option[1]} · ${englishLanguageNames[value]}`);
  if(typeof window!=='undefined'&&'speechSynthesis' in window&&typeof SpeechSynthesisUtterance!=='undefined'){
   announceSelectedLanguage(value,option[1],option[2],window.speechSynthesis,SpeechSynthesisUtterance);
  }
 }
